// The Exchange's unit of truth: the fact. Payload shapes are transcribed from
// the intropy CLI's wire contracts (intropy-cli/web/src/api.ts and
// internal/deploy/result.go); the portal renders them as served and joins
// them — it never re-derives what a command already said.

/** Where a fact came from: the command that emitted it, verbatim. */
export interface FactSourceStamp {
  /** The CLI verb or host verb that produced the payload, e.g. "deploy status". */
  command: string
  /** CLI version that ran. */
  version: string
  /** Who ran it — a person for pins and promotes, "ci" for emissions. */
  actor?: string
}

export type FactKind =
  | 'component.scaffolded'
  | 'release.created'
  | 'env.pinned'
  | 'env.promoted'
  | 'env.synced'
  | 'gate.pending'
  | 'contract.changed'
  | 'topology.observed'
  | 'deploy.status'

export interface Fact<P = unknown> {
  id: string
  /** Subject identity: intropy://<customer>/<domain>/<system>[/<component>] */
  urn: string
  kind: FactKind
  /** RFC 3339. */
  observedAt: string
  source: FactSourceStamp
  payload: P
}

// --- topology.intropy.io/v1 (subset the portal renders) ---

export interface TopicRef {
  pubsub: string
  topic: string
}

export interface Publication {
  port?: string
  pubsub: string
  topic: string
}

export interface ConnectorUse {
  connector: string
  direction: 'in' | 'out'
}

export interface TopologyComponent {
  name: string
  /** Block kind: extractor, loader, transactionalIntegration, … */
  kind: string
  subscribes?: TopicRef[]
  publishes?: Publication[]
  connectors?: ConnectorUse[]
}

export interface TopologyTopic {
  pubsub: string
  topic: string
  /** Fully-qualified contract type name — resolves against contracts[]. */
  contract?: string
  publishers?: string[]
  subscribers?: string[]
}

export interface TopologyTransport {
  type: string
  supportsInput: boolean
  supportsOutput: boolean
}

export interface TopologyConnector {
  name: string
  externalSystem?: string
  transport: TopologyTransport
  deployedTransport?: TopologyTransport
  directions?: Array<'in' | 'out'>
  usedBy?: string[]
}

export interface JsonSchema {
  type?: string | string[]
  format?: string
  properties?: Record<string, JsonSchema>
  required?: string[]
  items?: JsonSchema
  enum?: unknown[]
}

export interface Contract {
  /** Fully-qualified type name — an alias, scoped to its system. */
  name: string
  kind?: string
  /** Bare type name — the join key to scaffold values. */
  shortName?: string
  mediaType?: string
  /** Hash of the schema's canonical form; equal fingerprints mean equal
   *  shapes across systems. The global identity of a contract. */
  fingerprint?: string
  schema?: JsonSchema
}

export interface Topology {
  apiVersion: string
  system: string
  components?: TopologyComponent[]
  topics?: TopologyTopic[]
  connectors?: TopologyConnector[]
  contracts?: Contract[]
}

// --- deploy status (internal/deploy result types, rendered as served) ---

export interface ResultPin {
  image: string
  digest: string
  tag?: string
}

export interface EnvironmentStatus {
  environment: string
  appName: string
  onboarded: boolean
  reason?: string
  release?: string
  sourceCommit?: string
  pins?: ResultPin[]
  revision?: string
  deployedAt?: string
  syncPolicy: 'auto' | 'manual' | string
  syncStatus?: string
  healthStatus?: string
  /** A committed overlay change ArgoCD has not applied. For a manual
   *  environment that is an unspent gate at rest, not a fault. */
  pending: boolean
}

export interface StatusResult {
  component: string
  domain: string
  system: string
  kind: 'service' | 'shared' | string
  /** In promotion order: the last entry is the furthest downstream. */
  environments: EnvironmentStatus[]
  /** Every onboarded environment pins the identical digest for every image. */
  consistent: boolean
  /** The command's own sentence — render as served, never re-derive. */
  summary: string
  notes?: string[]
}

// --- release manifest (internal/release) ---

export interface ReleaseChange {
  commit: string
  subject: string
}

export interface ReleaseManifest {
  component: string
  version: string
  createdAt: string
  createdBy: string
  source: { commit: string; ref?: string; repo?: string }
  images: Array<{ name: string; digest: string }>
  notes?: string
  changes?: ReleaseChange[]
}

// --- scaffold record (subset) ---

export interface ScaffoldRecord {
  template: string
  version: string
  blockKind?: string
  dataFlow?: 'in' | 'out'
}

// --- ledger event payloads ---

export interface PinPayload {
  component: string
  environment: string
  release?: string
  image: string
  digest: string
  promotedFrom?: string
}

export interface SyncPayload {
  component: string
  environment: string
  revision: string
  healthStatus?: string
}

export interface GatePayload {
  component: string
  environment: string
  release?: string
  since: string
}

export interface ContractChangedPayload {
  shortName: string
  from: string
  to: string
  /** The release of the emitting component that introduced the new shape. */
  release: string
  component: string
}

// --- knowledge (OKF v0.2 pilot profile) ---

export interface KnowledgeDoc {
  slug: string
  type: 'Intropy Concept' | 'Intropy Workflow' | 'Intropy Playbook' | 'Intropy Contract'
  title: string
  description: string
  tags: string[]
  status: 'draft' | 'verified'
  /** CLI verbs the doc relates to — the binding hook for command-oriented surfaces. */
  commands: string[]
  /** Markdown-ish body, rendered as plain paragraphs in the PoC. */
  body: string[]
  /** Playbook triage rows, when the doc has them. */
  triage?: Array<{ symptom: string; boundary: string; evidence: string; nextAction: string }>
}

// --- diagram bindings (the diagramming tool's shapes bound to URNs) ---

export interface DiagramBinding {
  shape: string
  diagram: string
  /** Bound URN; absent means the shape was drawn but never bound. */
  urn?: string
  state: 'live' | 'stale' | 'unbound'
  /** Why the binding is not live, in the reconciler's words. */
  note?: string
}

/** Hand-recorded fingerprint timeline per (system, shortName): which release
 *  of which component introduced each shape. Real ingestion derives this from
 *  successive topology.observed facts; the fixture states it directly. */
export interface FingerprintEra {
  system: string
  shortName: string
  fingerprint: string
  sinceRelease: string
  component: string
}

// URNs carry the customer dimension from day one so a fleet-wide view later
// is a merge, not a migration: intropy://<customer>/<domain>/<system>[/<component>]

export interface Urn {
  customer: string
  domain: string
  system: string
  component?: string
}

export function urn(customer: string, domain: string, system: string, component?: string): string {
  const base = `intropy://${customer}/${domain}/${system}`
  return component ? `${base}/${component}` : base
}

export function parseUrn(value: string): Urn | undefined {
  const m = value.match(/^intropy:\/\/([^/]+)\/([^/]+)\/([^/]+)(?:\/([^/]+))?$/)
  if (!m) return undefined
  return { customer: m[1], domain: m[2], system: m[3], component: m[4] }
}

/** The path segments after the customer — what page routes are built from. */
export function urnPath(value: string): string {
  const parsed = parseUrn(value)
  if (!parsed) return value
  return [parsed.domain, parsed.system, parsed.component].filter(Boolean).join('/')
}

export function shortSha(commit: string): string {
  return commit.slice(0, 7)
}

