import type {
  ContractChangedPayload,
  Fact,
  GatePayload,
  PinPayload,
  ScaffoldRecord,
  SyncPayload,
} from '../domain/types'
import { urn } from '../domain/urn'
import { FP_ORDER_CONFIRMED, FP_ORDER_CONFIRMED_OLD } from './topologies'

// The ledger: what changed, when, by whom. Each fact's payload is what the
// emitting source already records — GitOps Deploy-* trailers for pins and
// promotes, ArgoCD for syncs, the scaffold record for creations.

let seq = 0
function fact<P>(
  kind: Fact['kind'],
  urnValue: string,
  observedAt: string,
  source: Fact['source'],
  payload: P,
): Fact<P> {
  seq += 1
  return { id: `ledger-${String(seq).padStart(3, '0')}`, urn: urnValue, kind, observedAt, source, payload }
}

const scaffold = (
  domain: string,
  system: string,
  component: string,
  at: string,
  record: ScaffoldRecord,
) =>
  fact<ScaffoldRecord>('component.scaffolded', urn('acme', domain, system, component), at, {
    command: 'int create',
    version: '0.7.0',
    actor: 'jonas',
  }, record)

const pin = (
  domain: string,
  system: string,
  component: string,
  at: string,
  actor: string,
  payload: PinPayload,
  promoted = false,
) =>
  fact<PinPayload>(promoted ? 'env.promoted' : 'env.pinned', urn('acme', domain, system, component), at, {
    command: promoted ? 'deploy promote' : 'deploy pin',
    version: '0.9.2',
    actor,
  }, payload)

const sync = (domain: string, system: string, component: string, at: string, payload: SyncPayload) =>
  fact<SyncPayload>('env.synced', urn('acme', domain, system, component), at, {
    command: 'argocd (observed)',
    version: '0.9.2',
    actor: 'argocd',
  }, payload)

