  }, true),
  fact<GatePayload>(
    'gate.pending',
    urn('acme', 'finance', 'invoicing', 'invoice-builder'),
    '2026-07-30T17:06:00Z',
    { command: 'deploy status', version: '0.9.2', actor: 'reconciler' },
