export const monitoringBase = 'https://monitor.acme.example/d/intropy-flow'

/** Deep link into the monitoring tool, pre-scoped the way the outbound
 *  integration promises: URN identity as the label scheme. */
export function monitoringLink(system: string, component?: string, environment = 'prod'): string {
  const params = new URLSearchParams({ system, env: environment })
  if (component) params.set('component', component)
  return `${monitoringBase}?${params.toString()}`
}

