// Pure folds from facts to page views. Everything here joins what the CLI
// said; nothing invents wiring or re-derives a summary.

import type {
  Fact,
  FingerprintEra,
  ReleaseManifest,
  StatusResult,
  Topology,
} from '../domain/types'
import { parseUrn, urn } from '../domain/urn'
import type {
  ContractRow,
  ConnectorRow,
  EstateComponentRow,
  EstateSystemRow,
  EstateView,
  MapEdge,
  MapGraph,
  MapNode,
  SystemView,
} from './source'
import type { DiagramBinding } from '../domain/types'

export function compareVersions(a: string, b: string): number {
  const pa = a.split('.').map(Number)
  const pb = b.split('.').map(Number)
  for (let i = 0; i < Math.max(pa.length, pb.length); i += 1) {
    const d = (pa[i] ?? 0) - (pb[i] ?? 0)
    if (d !== 0) return d
  }
  return 0
}

export function buildEstate(
  customer: string,
  statusFacts: Array<Fact<StatusResult>>,
): EstateView {
  const systems = new Map<string, EstateSystemRow>()
  let readAt = ''
  for (const fact of statusFacts) {
    const parsed = parseUrn(fact.urn)
    if (!parsed) continue
    readAt = readAt > fact.observedAt ? readAt : fact.observedAt
    const key = `${parsed.domain}/${parsed.system}`
    let row = systems.get(key)
    if (!row) {
      row = {
        urn: urn(customer, parsed.domain, parsed.system),
        domain: parsed.domain,
        system: parsed.system,
        components: [],
        consistent: true,
        pendingGates: 0,
      }
      systems.set(key, row)
    }
    row.components.push({
      urn: fact.urn,
      component: fact.payload.component,
      status: fact.payload,
      observedAt: fact.observedAt,
    })
    if (!fact.payload.consistent) row.consistent = false
    row.pendingGates += fact.payload.environments.filter((e) => e.pending).length
  }

  const domains = new Map<string, EstateSystemRow[]>()
  for (const row of systems.values()) {
    row.components.sort((a, b) => a.component.localeCompare(b.component))
    const list = domains.get(row.domain) ?? []
    list.push(row)
    domains.set(row.domain, list)
  }

  const domainList = [...domains.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([domain, rows]) => ({ domain, systems: rows.sort((a, b) => a.system.localeCompare(b.system)) }))

  const all = [...systems.values()]
  return {
    customer,
    readAt,
    domains: domainList,
    totals: {
      systems: all.length,
      components: all.reduce((n, s) => n + s.components.length, 0),
      inconsistent: all.reduce(
        (n, s) => n + s.components.filter((c) => !c.status.consistent).length,
        0,
      ),
      pendingGates: all.reduce((n, s) => n + s.pendingGates, 0),
    },
  }
}

export function buildContracts(
  topologyFacts: Array<Fact<Topology>>,
  statusFacts: Array<Fact<StatusResult>>,
  eras: FingerprintEra[],
): ContractRow[] {
  const rows = new Map<string, ContractRow>()

  for (const fact of topologyFacts) {
    const parsed = parseUrn(fact.urn)
    if (!parsed) continue
    const topo = fact.payload
    for (const contract of topo.contracts ?? []) {
      if (!contract.fingerprint) continue
      let row = rows.get(contract.fingerprint)
      if (!row) {
        row = {
          fingerprint: contract.fingerprint,
          shortName: contract.shortName ?? contract.name,
          mediaType: contract.mediaType,
          schema: contract.schema,
          aliases: [],
          systems: [],
          domains: [],
          componentCount: 0,
          drift: [],
          observedAt: fact.observedAt,
        }
        rows.set(contract.fingerprint, row)
      }
      const topics = (topo.topics ?? []).filter((t) => t.contract === contract.name)
      const publishers = [...new Set(topics.flatMap((t) => t.publishers ?? []))]
      const subscribers = [...new Set(topics.flatMap((t) => t.subscribers ?? []))]
      row.aliases.push({
        system: topo.system,
        domain: parsed.domain,
        name: contract.name,
        publishers,
        subscribers,
      })
      if (!row.systems.includes(topo.system)) row.systems.push(topo.system)
      if (!row.domains.includes(parsed.domain)) row.domains.push(parsed.domain)
      row.componentCount += publishers.length + subscribers.length
    }
  }

  // Drift: an environment pinned to a release older than the one that
  // introduced the system's current shape still speaks the previous shape.
  for (const row of rows.values()) {
    for (const alias of row.aliases) {
      const systemEras = eras
        .filter((e) => e.system === alias.system && e.shortName === row.shortName)
        .sort((a, b) => compareVersions(a.sinceRelease, b.sinceRelease))
      const current = systemEras.find((e) => e.fingerprint === row.fingerprint)
      if (!current) continue
      const status = statusFacts.find(
        (f) => f.payload.system === alias.system && f.payload.component === current.component,
      )
      if (!status) continue
      for (const env of status.payload.environments) {
        if (!env.release) continue
        if (compareVersions(env.release, current.sinceRelease) < 0) {
          const idx = systemEras.indexOf(current)
          const previous = idx > 0 ? systemEras[idx - 1] : undefined
          row.drift.push({
            system: alias.system,
            component: current.component,
            environment: env.environment,
            pinnedRelease: env.release,
            runsFingerprint: previous?.fingerprint ?? 'unknown',
            currentSinceRelease: current.sinceRelease,
          })
        }
      }
    }
  }

  return [...rows.values()].sort((a, b) => b.systems.length - a.systems.length)
}

export function buildSystemView(
  domain: string,
  system: string,
  topologyFacts: Array<Fact<Topology>>,
  statusFacts: Array<Fact<StatusResult>>,
  releaseFacts: Array<Fact<ReleaseManifest>>,
): SystemView | undefined {
  const topoFact = topologyFacts.find((f) => {
    const parsed = parseUrn(f.urn)
    return parsed?.domain === domain && parsed?.system === system
  })
  if (!topoFact) return undefined
  return {
    urn: topoFact.urn,
    domain,
    system,
    topology: topoFact.payload,
    observedAt: topoFact.observedAt,
    statuses: statusFacts
      .filter((f) => f.payload.system === system)
      .map((f) => ({
        urn: f.urn,
        component: f.payload.component,
        status: f.payload,
        observedAt: f.observedAt,
      }))
      .sort((a, b) => a.component.localeCompare(b.component)),
    releases: releaseFacts
      .filter((f) => parseUrn(f.urn)?.system === system)
      .sort((a, b) => b.payload.createdAt.localeCompare(a.payload.createdAt)),
  }
}

export function buildConnectors(topologyFacts: Array<Fact<Topology>>): ConnectorRow[] {
  const rows = new Map<string, ConnectorRow>()
  for (const fact of topologyFacts) {
    const parsed = parseUrn(fact.urn)
    if (!parsed) continue
    for (const connector of fact.payload.connectors ?? []) {
      const external = connector.externalSystem ?? connector.name
      let row = rows.get(external)
      if (!row) {
        row = { externalSystem: external, connectors: [] }
        rows.set(external, row)
      }
      row.connectors.push({ system: fact.payload.system, domain: parsed.domain, connector })
    }
  }
  return [...rows.values()].sort((a, b) => b.connectors.length - a.connectors.length)
}

export function buildMap(
  topologyFacts: Array<Fact<Topology>>,
  statusFacts: Array<Fact<StatusResult>>,
  bindings: DiagramBinding[],
): MapGraph {
  const nodes: MapNode[] = []
  const edges: MapEdge[] = []

  const externalUse = new Map<string, Set<string>>()
  for (const fact of topologyFacts) {
    for (const connector of fact.payload.connectors ?? []) {
      const external = connector.externalSystem ?? connector.name
      const set = externalUse.get(external) ?? new Set<string>()
      set.add(fact.payload.system)
      externalUse.set(external, set)
    }
  }

  for (const fact of topologyFacts) {
    const parsed = parseUrn(fact.urn)
    const system = fact.payload.system
    const statuses = statusFacts.filter((f) => f.payload.system === system)
    const staleBinding = bindings.find(
      (b) => b.state === 'stale' && b.urn !== undefined && parseUrn(b.urn)?.system === system,
    )
    nodes.push({
      id: system,
      label: system,
      kind: 'system',
      domain: parsed?.domain,
      consistent: statuses.every((f) => f.payload.consistent),
      pendingGates: statuses.reduce(
        (n, f) => n + f.payload.environments.filter((e) => e.pending).length,
        0,
      ),
      drift: staleBinding ? `diagram binds ${staleBinding.shape.split(' ')[0]} -> not declared` : undefined,
    })
  }

  for (const [external, users] of externalUse) {
    nodes.push({ id: `ext:${external}`, label: external, kind: 'external' })
    const provenance = users.size > 1 ? 'mediated' : 'declared'
    for (const fact of topologyFacts) {
      for (const connector of fact.payload.connectors ?? []) {
        if ((connector.externalSystem ?? connector.name) !== external) continue
        for (const direction of connector.directions ?? []) {
          const [from, to] =
            direction === 'in'
              ? [`ext:${external}`, fact.payload.system]
              : [fact.payload.system, `ext:${external}`]
          edges.push({
            id: `conn:${connector.name}:${fact.payload.system}:${direction}`,
            from,
            to,
            provenance,
            label: `${connector.name} (${(connector.deployedTransport ?? connector.transport).type})`,
          })
        }
      }
    }
  }

  // Derived edges: a system that publishes a shape outward -> every system
  // that subscribes to the same fingerprint. Dashed, never claimed as flow.
  const byFingerprint = new Map<string, Array<{ system: string; publishes: boolean; subscribes: boolean }>>()
  for (const fact of topologyFacts) {
    const topo = fact.payload
    for (const contract of topo.contracts ?? []) {
      if (!contract.fingerprint) continue
      const topics = (topo.topics ?? []).filter((t) => t.contract === contract.name)
      const entry = {
        system: topo.system,
        publishes: topics.some((t) => (t.publishers ?? []).length > 0),
        subscribes: topics.some((t) => (t.subscribers ?? []).length > 0),
      }
      const list = byFingerprint.get(contract.fingerprint) ?? []
      list.push(entry)
      byFingerprint.set(contract.fingerprint, list)
    }
  }
  for (const [fingerprint, entries] of byFingerprint) {
    if (entries.length < 2) continue
    for (const pub of entries.filter((e) => e.publishes)) {
      for (const sub of entries.filter((e) => e.subscribes && e.system !== pub.system)) {
        edges.push({
          id: `derived:${fingerprint}:${pub.system}:${sub.system}`,
          from: pub.system,
          to: sub.system,
          provenance: 'derived',
          label: `same shape @ ${fingerprint}`,
        })
      }
    }
  }

  return { nodes, edges, bindings }
}

import { describe, expect, it } from 'vitest'
import { deployStatusFacts, fingerprintEras } from '../fixtures/deploy'
import { diagramBindings } from '../fixtures/knowledge'
import { topologyFacts, FP_ORDER_CONFIRMED, FP_ORDER_CONFIRMED_OLD } from '../fixtures/topologies'
import { buildContracts, buildEstate, buildMap, compareVersions } from './projections'

describe('compareVersions', () => {
  it('orders semantic versions numerically, not lexically', () => {
    expect(compareVersions('1.8.0', '1.10.0')).toBeLessThan(0)
    expect(compareVersions('2.4.0', '2.3.1')).toBeGreaterThan(0)
    expect(compareVersions('1.0', '1.0.0')).toBe(0)
  })
})

describe('buildEstate', () => {
  const estate = buildEstate('acme', deployStatusFacts)

  it('groups systems under domains', () => {
    expect(estate.domains.map((d) => d.domain)).toEqual(['commerce', 'finance'])
    const commerce = estate.domains[0]
    expect(commerce.systems.map((s) => s.system)).toEqual(['erp-orders', 'webshop-sync'])
  })

  it('rolls up totals from the status facts as served', () => {
    expect(estate.totals.systems).toBe(3)
    expect(estate.totals.components).toBe(8)
    expect(estate.totals.inconsistent).toBe(1)
    expect(estate.totals.pendingGates).toBe(1)
  })

  it('marks a system inconsistent when any component disagrees', () => {
    const webshop = estate.domains[0].systems.find((s) => s.system === 'webshop-sync')
    expect(webshop?.consistent).toBe(false)
    const erp = estate.domains[0].systems.find((s) => s.system === 'erp-orders')
    expect(erp?.consistent).toBe(true)
  })
})

describe('buildContracts', () => {
  const contracts = buildContracts(topologyFacts, deployStatusFacts, fingerprintEras)
  const orderConfirmed = contracts.find((c) => c.fingerprint === FP_ORDER_CONFIRMED)

  it('joins the same fingerprint across systems under their local aliases', () => {
    expect(orderConfirmed).toBeDefined()
    expect(orderConfirmed?.systems.sort()).toEqual(['erp-orders', 'invoicing', 'webshop-sync'])
    expect(orderConfirmed?.aliases.map((a) => a.name).sort()).toEqual([
      'Acme.Finance.OrderConfirmed',
      'Acme.Orders.OrderConfirmed',
      'Shop.Orders.Confirmed',
    ])
  })

  it('flags the environment pinned to a release older than the current shape', () => {
    expect(orderConfirmed?.drift).toHaveLength(1)
    const drift = orderConfirmed?.drift[0]
    expect(drift?.system).toBe('webshop-sync')
    expect(drift?.environment).toBe('prod')
    expect(drift?.pinnedRelease).toBe('1.7.2')
    expect(drift?.runsFingerprint).toBe(FP_ORDER_CONFIRMED_OLD)
  })

  it('does not flag systems whose environments all run the current shape', () => {
    const systems = orderConfirmed?.drift.map((d) => d.system)
    expect(systems).not.toContain('erp-orders')
    expect(systems).not.toContain('invoicing')
  })
})

describe('buildMap', () => {
  const graph = buildMap(topologyFacts, deployStatusFacts, diagramBindings)

  it('renders a shared external system as mediated and a private one as declared', () => {
    const sapEdges = graph.edges.filter((e) => e.from === 'ext:SAP ECC' || e.to === 'ext:SAP ECC')
    expect(sapEdges.length).toBeGreaterThan(1)
    expect(sapEdges.every((e) => e.provenance === 'mediated')).toBe(true)
    const vismaEdges = graph.edges.filter((e) => e.to === 'ext:Visma eEkonomi')
    expect(vismaEdges.every((e) => e.provenance === 'declared')).toBe(true)
  })

  it('derives dashed same-shape edges from publisher systems to subscriber systems', () => {
    const derived = graph.edges.filter((e) => e.provenance === 'derived')
    const pairs = derived.map((e) => `${e.from}->${e.to}`)
    expect(pairs).toContain('erp-orders->webshop-sync')
    expect(pairs).toContain('erp-orders->invoicing')
    // No system claims to publish a shape it only consumes.
    expect(pairs.every((p) => p.startsWith('erp-orders->') || !p.includes('erp-orders'))).toBe(true)
  })

  it('carries the stale diagram binding as drift on the bound system', () => {
    const webshop = graph.nodes.find((n) => n.id === 'webshop-sync')
    expect(webshop?.drift).toContain('ftp-legacy')
  })
})

/* The Exchange — registry-of-record visual language.
   Cool paper ground, ink slate text, verdigris accent, amber attention,
   rust disagreement. Fraunces for surface titles, Public Sans for UI,
   IBM Plex Mono for everything machine-true. */

:root {
  --paper: #f2f5f4;
  --card: #fbfcfb;
  --ink: #1d2a2e;
  --muted: #5d6f6e;
  --faint: #8ba09d;
  --hairline: #d9e2df;
  --verdigris: #2a7a68;
  --verdigris-deep: #1f5a4d;
  --verdigris-bg: #e3efeb;
  --amber: #a06008;
  --amber-bg: #f6ead3;
  --rust: #a63d32;
  --rust-bg: #f5e3df;
  --mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --body: 'Public Sans Variable', system-ui, -apple-system, sans-serif;
  --display: 'Fraunces Variable', Georgia, serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  font-family: var(--body);
  font-size: 14.5px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--verdigris-deep);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

a:focus-visible,
button:focus-visible,
select:focus-visible {
  outline: 2px solid var(--verdigris);
  outline-offset: 2px;
}

code,
.mono {
  font-family: var(--mono);
  font-size: 0.92em;
}

/* --- shell --- */

.shell {
  display: grid;
  grid-template-columns: 216px 1fr;
  min-height: 100vh;
}

.rail {
  border-right: 1px solid var(--hairline);
  padding: 28px 20px;
  display: flex;
  flex-direction: column;
  gap: 28px;
  position: sticky;
  top: 0;
  height: 100vh;
}

.wordmark {
  font-family: var(--display);
  font-size: 21px;
  font-weight: 560;
  font-variation-settings: 'SOFT' 40, 'WONK' 1;
  letter-spacing: 0.01em;
  color: var(--ink);
}

.wordmark small {
  display: block;
  font-family: var(--body);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--faint);
  margin-top: 4px;
}

.rail nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.rail nav a {
  padding: 7px 10px;
  border-radius: 6px;
  color: var(--muted);
