// The portal's signature mark: a deterministic 4x4 glyph drawn from the
// contract fingerprint. Equal fingerprints render the identical mark, so two
// systems speaking the same shape is visible before it is readable.

const PALETTE = ['#2a7a68', '#1f5a4d', '#38617a', '#5b4a78', '#a06008', '#a63d32']

function bits(fingerprint: string): { cells: boolean[]; color: string } {
  const hex = fingerprint.replace(/[^0-9a-f]/gi, '').padEnd(8, '0').slice(0, 8)
  const value = Number.parseInt(hex, 16)
  const cells: boolean[] = []
  // Left half from the hash, right half mirrored: symmetric, stamp-like.
  for (let row = 0; row < 4; row += 1) {
    const left = (value >> (row * 4)) & 0b11
    const mid = (value >> (row * 4 + 2)) & 0b11
    const rowCells = [(left & 1) === 1, (left & 2) === 2, (mid & 1) === 1]
    cells.push(rowCells[0], rowCells[1], rowCells[2], rowCells[1] !== rowCells[0])
  }
  return { cells, color: PALETTE[value % PALETTE.length] }
}

export function FingerprintGlyph({ fingerprint, size = 20 }: { fingerprint: string; size?: number }) {
  const { cells, color } = bits(fingerprint)
  const cell = size / 4
  return (
    <svg
      className="glyph"
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      role="img"
      aria-label={`shape ${fingerprint}`}
    >
      <rect width={size} height={size} fill={color} opacity={0.12} rx={3} />
      {cells.map((on, i) =>
        on ? (
          <rect
            key={i}
            x={(i % 4) * cell + 1}
            y={Math.floor(i / 4) * cell + 1}
            width={cell - 2}
            height={cell - 2}
            fill={color}
            rx={1}
          />
        ) : null,
      )}
    </svg>
  )
}

import type { ReactNode } from 'react'
import type { EnvironmentStatus, FactSourceStamp, JsonSchema } from '../domain/types'
import { shortSha } from '../domain/urn'

export function fmtTime(iso: string): string {
  const d = new Date(iso)
  return d.toLocaleString('en-GB', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'UTC',
  })
}

export function fmtDay(iso: string): string {
  return new Date(iso).toLocaleDateString('en-GB', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    timeZone: 'UTC',
  })
}

/** Every claim names its source: the stamp under each card. */
export function Provenance({ source, at }: { source: FactSourceStamp; at: string }) {
  return (
    <div className="provenance">
      as reported by <code>{source.command}</code> @ {fmtTime(at)}
      {source.actor ? <> · {source.actor}</> : null}
    </div>
  )
}

export function digest7(digest: string): string {
  return shortSha(digest.replace(/^sha256:/, ''))
}

/** The promotion ladder: dev -> staging -> prod, releases as pinned. */
export function EnvLadder({
  environments,
  behindEnv,
}: {
  environments: EnvironmentStatus[]
  behindEnv?: string
}) {
  return (
    <div className="ladder">
      {environments.map((env, i) => (
        <span key={env.environment} className="row" style={{ gap: 6 }}>
          {i > 0 && <span className="arrow">-&gt;</span>}
          <span
            className={`rung${env.pending ? ' pending' : ''}${env.environment === behindEnv ? ' behind' : ''}`}
            title={`${env.appName} · sync ${env.syncStatus ?? 'unread'} · ${env.syncPolicy}`}
          >
            {env.environment} <strong>{env.release ?? shortSha(env.sourceCommit ?? '')}</strong>
            {env.pins?.[0] ? <> @ {digest7(env.pins[0].digest)}</> : null}
            {env.pending ? ' · gate' : ''}
          </span>
        </span>
      ))}
    </div>
  )
}

/** Rendered command — the portal never acts, it hands you the verb. */
export function Command({ children }: { children: ReactNode }) {
  return <div className="command">{children}</div>
}

export function SchemaTree({ schema, name }: { schema: JsonSchema; name?: string }) {
  return (
    <div className="schema-tree">
      <ul>
        <SchemaNode schema={schema} name={name} required={false} />
      </ul>
    </div>
  )
}

function SchemaNode({
  schema,
  name,
  required,
}: {
  schema: JsonSchema
  name?: string
  required: boolean
}) {
  const type = Array.isArray(schema.type) ? schema.type.join(' | ') : schema.type
  const label = schema.enum
    ? `enum(${schema.enum.length})`
    : schema.items
      ? `${type ?? 'array'}[]`
      : (type ?? 'unknown')
  const children = schema.items?.properties ?? schema.properties
  const childRequired = schema.items?.required ?? schema.required ?? []
  return (
    <li>
      {name ? <span>{name}</span> : null}{' '}
      <span className="field-type">{label}</span>
      {required ? <span className="field-req">req</span> : null}
      {children ? (
        <ul>
          {Object.entries(children).map(([key, child]) => (
            <SchemaNode key={key} schema={child} name={key} required={childRequired.includes(key)} />
          ))}
        </ul>
      ) : null}
    </li>
  )
}

import { useEffect, useState } from 'react'

/** Async fixture reads look like a future real API: pages await the source. */
export function useData<T>(load: () => Promise<T>, deps: unknown[] = []): T | undefined {
  const [value, setValue] = useState<T>()
  useEffect(() => {
    let live = true
    load().then((v) => {
      if (live) setValue(v)
    })
    return () => {
      live = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
  return value
}

