  const view = useData(() => mockSource.system(domain, system), [domain, system])
  if (!view) {
    return <div className="empty">No host has emitted a topology for this system.</div>
  }

  const topo = view.topology

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">
          system · {view.domain} · <span className="mono">{view.urn}</span>
        </div>
        <h1>{view.system}</h1>
        <div className="row">
          <span className="chip mono">{topo.apiVersion}</span>
          <a
            className="chip external-link"
            href={monitoringLink(view.system)}
            target="_blank"
            rel="noreferrer"
          >
            monitoring
          </a>
        </div>
      </header>

      <h2>Components</h2>
      <div className="stack">
        {(topo.components ?? []).map((component) => {
          const status = view.statuses.find((s) => s.component === component.name)
          return (
            <div key={component.name} className="card">
              <div className="row" style={{ justifyContent: 'space-between' }}>
                <h3 style={{ margin: 0 }}>
                  <span className="mono">{component.name}</span>{' '}
                  <span className="chip" style={{ marginLeft: 8 }}>
                    {component.kind}
                  </span>
                </h3>
                {status && !status.status.consistent && (
                  <span className="chip bad">environments disagree</span>
                )}
              </div>
              <div className="small muted" style={{ margin: '8px 0' }}>
                {(component.subscribes ?? []).map((s) => (
                  <div key={s.topic}>
                    subscribes <span className="mono">{s.topic}</span>
                  </div>
                ))}
                {(component.publishes ?? []).map((p) => (
                  <div key={p.topic}>
                    publishes <span className="mono">{p.topic}</span>
                  </div>
                ))}
                {(component.connectors ?? []).map((c) => (
                  <div key={c.connector}>
                    {c.direction === 'in' ? (
                      <>
                        <span className="mono">{c.connector}</span> -&gt; component
                      </>
                    ) : (
                      <>
                        component -&gt; <span className="mono">{c.connector}</span>
                      </>
                    )}
                  </div>
                ))}
              </div>
              {status && (
                <>
                  <EnvLadder environments={status.status.environments} />
                  <div className="summary-sentence" style={{ marginTop: 8 }}>
                    {status.status.summary}
                  </div>
                  <Provenance
                    source={{ command: 'deploy status', version: '0.9.2', actor: 'reconciler' }}
                    at={status.observedAt}
                  />
                </>
              )}
            </div>
          )
        })}
      </div>

      <div className="grid-2" style={{ marginTop: 36 }}>
        <section>
          <h2 style={{ marginTop: 0 }}>Contracts</h2>
          <div className="card">
            {(topo.contracts ?? []).map((contract) => (
              <div key={contract.name} className="row" style={{ marginBottom: 10 }}>
                {contract.fingerprint && <FingerprintGlyph fingerprint={contract.fingerprint} />}
                <Link to={`/contracts/${contract.fingerprint}`}>
                  <strong>{contract.shortName}</strong>
                </Link>
                <span className="mono small muted">{contract.name}</span>
                <span className="fp">@ {contract.fingerprint}</span>
              </div>
            ))}
          </div>
        </section>

        <section>
          <h2 style={{ marginTop: 0 }}>Connectors</h2>
          <div className="card">
            {(topo.connectors ?? []).map((connector) => (
              <div key={connector.name} style={{ marginBottom: 10 }}>
                <span className="mono">{connector.name}</span>{' '}
                <span className="muted small">
                  {connector.directions?.includes('in') ? '<- ' : '-> '}
                  {connector.externalSystem}
                </span>
                <div className="small muted">
                  local {connector.transport.type}
                  {connector.deployedTransport ? (
                    <> · deployed {connector.deployedTransport.type}</>
                  ) : null}{' '}
                  · used by {(connector.usedBy ?? []).join(', ')}
                </div>
              </div>
            ))}
          </div>
        </section>
