const nodeTypes = { system: SystemNode, external: ExternalNode }

const EDGE_STYLE = {
  declared: { stroke: '#1d2a2e', strokeWidth: 1.5 },
  mediated: { stroke: '#2a7a68', strokeWidth: 1.5 },
  derived: { stroke: '#a06008', strokeWidth: 1.5, strokeDasharray: '6 5' },
} as const

export function MapPage() {
  const graph = useData(() => mockSource.map())
  const navigate = useNavigate()

  const { nodes, edges } = useMemo(() => {
    if (!graph) return { nodes: [] as FlowNode[], edges: [] as Edge[] }
    const nodes: FlowNode[] = graph.nodes.map((node) => ({
      id: node.id,
      type: node.kind,
      position: POSITIONS[node.id] ?? { x: 100, y: 100 },
      data: { node },
    }))
    const edges: Edge[] = graph.edges.map((edge) => ({
      id: edge.id,
      source: edge.from,
      target: edge.to,
      label: edge.label,
      type: 'default',
      style: EDGE_STYLE[edge.provenance],
      labelStyle: { fontSize: 10, fill: '#5d6f6e', fontFamily: 'IBM Plex Mono, monospace' },
      labelBgStyle: { fill: '#fbfcfb', fillOpacity: 0.9 },
      animated: edge.provenance === 'derived',
    }))
    return { nodes, edges }
  }, [graph])

  if (!graph) return null

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">landscape map · render-only</div>
        <h1>The estate, as declared</h1>
        <p className="lede">
          Every edge comes from a declared topology or a provable join — the map never invents
          wiring. Intent stays in the diagramming tool; what it drew and reality disagree on shows
          up here as drift.
        </p>
      </header>

      <div className="map-wrap">
        <div>
          <div className="map-canvas">
            <ReactFlow
              nodes={nodes}
              edges={edges}
              nodeTypes={nodeTypes}
              fitView
              nodesDraggable={false}
              nodesConnectable={false}
              proOptions={{ hideAttribution: true }}
              onNodeClick={(_, node) => {
                const mapNode = (node.data as { node: MapNode }).node
                if (mapNode.kind === 'system') {
                  navigate(`/systems/${SYSTEM_DOMAIN[mapNode.id] ?? 'commerce'}/${mapNode.id}`)
                }
              }}
            >
              <Background gap={24} color="#dde6e3" />
            </ReactFlow>
          </div>
          <div className="legend">
            <span>
              <span className="swatch" /> declared connector
            </span>
            <span>
              <span className="swatch mediated" /> mediated by a shared external system
            </span>
            <span>
              <span className="swatch derived" /> derived: same shape (fingerprint equality)
            </span>
          </div>
        </div>

        <aside className="card">
          <h3>Diagram bindings</h3>
          <p className="small muted" style={{ marginTop: 0 }}>
            What the diagramming tool's shapes are bound to, and whether reality still agrees.
          </p>
          {graph.bindings.map((binding) => (
            <div key={binding.shape} style={{ marginBottom: 12 }}>
              <div className="row" style={{ gap: 8 }}>
                <span
                  className={`chip ${
                    binding.state === 'live' ? 'ok' : binding.state === 'stale' ? 'bad' : 'warn'
                  }`}
                >
                  {binding.state}
                </span>
                <strong className="small">{binding.shape}</strong>
              </div>
              <div className="small muted">{binding.diagram}</div>
              {binding.note && <div className="small muted">— {binding.note}</div>}
            </div>
          ))}
          <a
            className="chip external-link"
            href="https://diagrams.acme.example/order-flow-overview"
            target="_blank"
            rel="noreferrer"
          >
            open diagram
          </a>
        </aside>
      </div>
    </>
  )
}

import { useState } from 'react'
