  SyncPayload,
} from '../domain/types'
import { shortSha, urnPath } from '../domain/urn'
import { FingerprintGlyph } from '../components/FingerprintGlyph'

const KINDS = [
  'release.created',
  'env.pinned',
  'env.promoted',
  'env.synced',
  'gate.pending',
  'contract.changed',
  'component.scaffolded',
]

const SYSTEMS = ['erp-orders', 'webshop-sync', 'invoicing']

function KindChip({ kind }: { kind: string }) {
  const tone = kind === 'gate.pending' ? 'warn' : kind === 'contract.changed' ? 'warn' : ''
  return <span className={`chip mono ${tone}`}>{kind}</span>
}

function FactLine({ fact }: { fact: Fact }) {
  switch (fact.kind) {
    case 'release.created': {
      const p = fact.payload as ReleaseManifest
      return (
        <>
          <span className="mono">
            {p.component} @ {p.version}
          </span>{' '}
          by {p.createdBy} — {(p.changes ?? []).length} change{(p.changes ?? []).length === 1 ? '' : 's'}
          {p.notes ? <span className="muted"> · {p.notes}</span> : null}
        </>
      )
    }
    case 'env.pinned':
    case 'env.promoted': {
      const p = fact.payload as PinPayload
      return (
        <>
          {p.promotedFrom ? (
            <>
              {p.promotedFrom} -&gt; <strong>{p.environment}</strong>
            </>
          ) : (
            <strong>{p.environment}</strong>
          )}{' '}
          <span className="mono">
            {p.component} @ {p.release} ({shortSha(p.digest.replace('sha256:', ''))})
          </span>
        </>
      )
    }
    case 'env.synced': {
      const p = fact.payload as SyncPayload
      return (
        <>
          <strong>{p.environment}</strong> applied{' '}
          <span className="mono">rev {p.revision}</span> · {p.healthStatus}
        </>
      )
    }
    case 'gate.pending': {
      const p = fact.payload as GatePayload
      return (
        <>
          <strong>{p.environment}</strong> holds a committed change for{' '}
          <span className="mono">
            {p.component} @ {p.release}
          </span>{' '}
          — an unspent manual gate, not a fault.
          <div style={{ marginTop: 8, maxWidth: 460 }}>
            <Command>
              intropy deploy sync {p.component} --env {p.environment}
            </Command>
          </div>
        </>
      )
    }
    case 'contract.changed': {
      const p = fact.payload as ContractChangedPayload
      return (
        <span className="row" style={{ gap: 6 }}>
          <span className="mono">{p.shortName}</span>
          <FingerprintGlyph fingerprint={p.from} size={14} />
          <span className="fp">{p.from}</span>
          <span className="mono">-&gt;</span>
          <FingerprintGlyph fingerprint={p.to} size={14} />
          <span className="fp">{p.to}</span>
          <span className="muted small">
            with {p.component} @ {p.release}
          </span>
        </span>
      )
    }
    case 'component.scaffolded': {
      const p = fact.payload as ScaffoldRecord
      return (
        <>
          scaffolded from template <span className="mono">{p.template}</span>
          {p.blockKind ? <span className="muted"> · {p.blockKind}</span> : null}
        </>
      )
    }
    default:
      return <span className="muted">{fact.kind}</span>
  }
}

export function LedgerPage() {
  const [kind, setKind] = useState('')
  const [system, setSystem] = useState('')
  const facts = useData(
    () => mockSource.ledger({ kind: kind || undefined, system: system || undefined }),
    [kind, system],
  )
  if (!facts) return null

  const byDay = new Map<string, Fact[]>()
  for (const fact of facts) {
    const day = fact.observedAt.slice(0, 10)
    byDay.set(day, [...(byDay.get(day) ?? []), fact])
  }

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">ledger</div>
        <h1>What changed, when, by whom</h1>
        <p className="lede">
          Releases, pins, promotions, and syncs across the estate, in the order they were
          observed. Every entry is a fact its source already records — GitOps trailers, release
          manifests, ArgoCD.
        </p>
      </header>

      <div className="filters">
        <select value={kind} onChange={(e) => setKind(e.target.value)} aria-label="Filter by kind">
          <option value="">every kind</option>
          {KINDS.map((k) => (
            <option key={k} value={k}>
              {k}
            </option>
          ))}
        </select>
        <select
          value={system}
          onChange={(e) => setSystem(e.target.value)}
          aria-label="Filter by system"
        >
          <option value="">every system</option>
          {SYSTEMS.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>
      </div>

      {facts.length === 0 && (
        <div className="empty">No facts match this filter. Widen it to see the estate move.</div>
      )}

      {[...byDay.entries()].map(([day, dayFacts]) => (
        <section key={day}>
          <div className="ledger-day">{fmtDay(day)}</div>
          <div className="card" style={{ padding: 0 }}>
            {dayFacts.map((fact) => (
              <div key={fact.id} className="fact-row">
                <span className="at">{fmtTime(fact.observedAt).slice(-5)}</span>
                <span>
                  <KindChip kind={fact.kind} />
                </span>
                <span className="what">
                  <div className="subject">{urnPath(fact.urn)}</div>
                  <FactLine fact={fact} />
                </span>
                <span className="stamp">
                  <code>{fact.source.command}</code>
                  {fact.source.actor ? ` · ${fact.source.actor}` : ''}
                </span>
              </div>
            ))}
          </div>
        </section>
      ))}
    </>
  )
}

