/** A neighbouring system in the flow: an external system named by a declared
 *  connector, or another portal system joined by fingerprint equality. */
export interface SystemNeighbor {
  name: string
  kind: 'external' | 'system'
  /** Route target for kind: system. */
  domain?: string
}

export interface SystemsTableRow {
  domain: string
  system: string
  sources: SystemNeighbor[]
  entities: string[]
  destinations: SystemNeighbor[]
  consistent: boolean
  pendingGates: number
}

export interface FactSource {
  estate(): Promise<EstateView>
  systemsTable(): Promise<SystemsTableRow[]>

/** One row per system: where its data comes from, what it speaks, where it
 *  goes. Neighbours are declared connectors' external systems plus other
 *  systems joined by fingerprint equality — never invented wiring. */
export function buildSystemsTable(
  topologyFacts: Array<Fact<Topology>>,
  statusFacts: Array<Fact<StatusResult>>,
): SystemsTableRow[] {
  // Which systems publish / subscribe each fingerprint, for the derived joins.
  const shapeUse = new Map<string, Array<{ system: string; publishes: boolean; subscribes: boolean }>>()
  for (const fact of topologyFacts) {
    const topo = fact.payload
    for (const contract of topo.contracts ?? []) {
      if (!contract.fingerprint) continue
      const topics = (topo.topics ?? []).filter((t) => t.contract === contract.name)
      const list = shapeUse.get(contract.fingerprint) ?? []
      list.push({
        system: topo.system,
        publishes: topics.some((t) => (t.publishers ?? []).length > 0),
        subscribes: topics.some((t) => (t.subscribers ?? []).length > 0),
      })
      shapeUse.set(contract.fingerprint, list)
    }
  }

  const domainOf = new Map<string, string>()
  for (const fact of topologyFacts) {
    const parsed = parseUrn(fact.urn)
    if (parsed) domainOf.set(fact.payload.system, parsed.domain)
  }

  const rows: SystemsTableRow[] = []
  for (const fact of topologyFacts) {
    const topo = fact.payload
    const domain = domainOf.get(topo.system) ?? ''
    const sources = new Map<string, SystemNeighbor>()
    const destinations = new Map<string, SystemNeighbor>()

    for (const connector of topo.connectors ?? []) {
      const external = connector.externalSystem ?? connector.name
      const neighbor: SystemNeighbor = { name: external, kind: 'external' }
      if (connector.directions?.includes('in')) sources.set(external, neighbor)
      if (connector.directions?.includes('out')) destinations.set(external, neighbor)
    }

    for (const [, uses] of shapeUse) {
      const mine = uses.find((u) => u.system === topo.system)
      if (!mine) continue
      for (const other of uses) {
        if (other.system === topo.system) continue
        const neighbor: SystemNeighbor = {
          name: other.system,
          kind: 'system',
          domain: domainOf.get(other.system),
        }
        if (mine.subscribes && other.publishes) sources.set(other.system, neighbor)
        if (mine.publishes && other.subscribes) destinations.set(other.system, neighbor)
      }
    }

    const entities = [
      ...new Set((topo.contracts ?? []).map((c) => c.shortName ?? c.name)),
    ].sort()

    const statuses = statusFacts.filter((f) => f.payload.system === topo.system)
    rows.push({
      domain,
      system: topo.system,
      sources: [...sources.values()].sort((a, b) => a.name.localeCompare(b.name)),
      entities,
      destinations: [...destinations.values()].sort((a, b) => a.name.localeCompare(b.name)),
      consistent: statuses.every((f) => f.payload.consistent),
      pendingGates: statuses.reduce(
        (n, f) => n + f.payload.environments.filter((e) => e.pending).length,
        0,
      ),
    })
  }

  return rows.sort(
    (a, b) => a.domain.localeCompare(b.domain) || a.system.localeCompare(b.system),
  )
}

