function NeighborList({ neighbors }: { neighbors: SystemNeighbor[] }) {
  if (neighbors.length === 0) return <span className="muted small">—</span>
  return (
    <span className="row" style={{ gap: 6 }}>
      {neighbors.map((neighbor) =>
        neighbor.kind === 'system' ? (
          <Link
            key={neighbor.name}
            className="chip"
            to={`/systems/${neighbor.domain}/${neighbor.name}`}
          >
            {neighbor.name}
          </Link>
        ) : (
          <span key={neighbor.name} className="chip">
            {neighbor.name}
          </span>
        ),
      )}
    </span>
  )
}

function distinct(rows: SystemsTableRow[], pick: (row: SystemsTableRow) => string[]): string[] {
  return [...new Set(rows.flatMap(pick))].sort()
}

function SystemsTable({ rows }: { rows: SystemsTableRow[] }) {
  const [name, setName] = useState('')
  const [source, setSource] = useState('')
  const [entity, setEntity] = useState('')
  const [destination, setDestination] = useState('')

  const options = useMemo(
    () => ({
      sources: distinct(rows, (r) => r.sources.map((n) => n.name)),
      entities: distinct(rows, (r) => r.entities),
      destinations: distinct(rows, (r) => r.destinations.map((n) => n.name)),
    }),
    [rows],
  )

  const filtered = rows.filter((row) => {
    if (name && !row.system.toLowerCase().includes(name.toLowerCase())) return false
    if (source && !row.sources.some((n) => n.name === source)) return false
    if (entity && !row.entities.includes(entity)) return false
    if (destination && !row.destinations.some((n) => n.name === destination)) return false
    return true
  })

  return (
    <table className="board systems-table">
      <thead>
        <tr>
          <th>
            system
            <input
              type="search"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="filter"
              aria-label="Filter by system name"
            />
          </th>
          <th>
            source systems
            <select
              value={source}
              onChange={(e) => setSource(e.target.value)}
              aria-label="Filter by source system"
            >
              <option value="">any</option>
              {options.sources.map((v) => (
                <option key={v}>{v}</option>
              ))}
            </select>
          </th>
          <th>
            entity
            <select
              value={entity}
              onChange={(e) => setEntity(e.target.value)}
              aria-label="Filter by entity"
            >
              <option value="">any</option>
              {options.entities.map((v) => (
                <option key={v}>{v}</option>
              ))}
            </select>
          </th>
          <th>
            destination systems
            <select
              value={destination}
              onChange={(e) => setDestination(e.target.value)}
              aria-label="Filter by destination system"
            >
              <option value="">any</option>
              {options.destinations.map((v) => (
                <option key={v}>{v}</option>
              ))}
            </select>
          </th>
        </tr>
      </thead>
      <tbody>
        {filtered.map((row) => (
          <tr key={row.system}>
            <td>
              <div className="eyebrow">{row.domain}</div>
              <Link to={`/systems/${row.domain}/${row.system}`}>
                <strong>{row.system}</strong>
              </Link>{' '}
              {!row.consistent && <span className="chip bad">disagree</span>}
              {row.pendingGates > 0 && <span className="chip warn">gate</span>}
            </td>
            <td>
              <NeighborList neighbors={row.sources} />
            </td>
            <td>
              <span className="row" style={{ gap: 6 }}>
                {row.entities.map((e) => (
                  <span key={e} className="chip mono">
                    {e}
                  </span>
                ))}
              </span>
            </td>
            <td>
              <NeighborList neighbors={row.destinations} />
            </td>
          </tr>
        ))}
        {filtered.length === 0 && (
          <tr>
            <td colSpan={4}>
              <span className="muted">No system matches this filter. Widen it.</span>
            </td>
          </tr>
        )}
      </tbody>
    </table>
  )
}

