import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { mockSource } from '../data/mock'
import { useData } from '../data/useData'
import type { SystemNeighbor, SystemsTableRow } from '../data/source'
import { fmtTime } from '../components/shared'

// The landing page is a Backstage-shaped catalog listing, oriented around
// systems: one dense row each, details one click away on the system page.

function NeighborList({ neighbors }: { neighbors: SystemNeighbor[] }) {
  if (neighbors.length === 0) return <span className="muted small">—</span>
  return (
    <span className="row" style={{ gap: 6 }}>
      {neighbors.map((neighbor) =>
        neighbor.kind === 'system' ? (
          <Link
            key={neighbor.name}
            className="chip"
            to={`/systems/${neighbor.domain}/${neighbor.name}`}
          >
            {neighbor.name}
          </Link>
        ) : (
          <span key={neighbor.name} className="chip">
            {neighbor.name}
          </span>
        ),
      )}
    </span>
  )
}

function distinct(rows: SystemsTableRow[], pick: (row: SystemsTableRow) => string[]): string[] {
  return [...new Set(rows.flatMap(pick))].sort()
}

function rowText(row: SystemsTableRow): string {
  return [
    row.system,
    row.domain,
    row.lifecycle,
    ...row.sources.map((n) => n.name),
    ...row.entities,
    ...row.destinations.map((n) => n.name),
  ]
    .join(' ')
    .toLowerCase()
}

export function EstatePage() {
  const rows = useData(() => mockSource.systemsTable())
  const estate = useData(() => mockSource.estate())
  const [query, setQuery] = useState('')
  const [domain, setDomain] = useState('')
  const [source, setSource] = useState('')
  const [entity, setEntity] = useState('')
  const [destination, setDestination] = useState('')
  const [lifecycle, setLifecycle] = useState('')

  const options = useMemo(
    () =>
      rows
        ? {
            domains: distinct(rows, (r) => [r.domain]),
            sources: distinct(rows, (r) => r.sources.map((n) => n.name)),
            entities: distinct(rows, (r) => r.entities),
            destinations: distinct(rows, (r) => r.destinations.map((n) => n.name)),
            lifecycles: distinct(rows, (r) => [r.lifecycle]),
          }
        : undefined,
    [rows],
  )

  if (!rows || !estate || !options) return null

  const filtered = rows.filter((row) => {
    if (query && !rowText(row).includes(query.toLowerCase())) return false
    if (domain && row.domain !== domain) return false
    if (source && !row.sources.some((n) => n.name === source)) return false
    if (entity && !row.entities.includes(entity)) return false
    if (destination && !row.destinations.some((n) => n.name === destination)) return false
    if (lifecycle && row.lifecycle !== lifecycle) return false
    return true
  })

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">
          systems catalog · {estate.customer} · read {fmtTime(estate.readAt)}
        </div>
        <h1>
          Systems <span className="count">({filtered.length})</span>
        </h1>
      </header>

      <div className="catalog-toolbar">
        <select value={domain} onChange={(e) => setDomain(e.target.value)} aria-label="Filter by domain">
          <option value="">domain</option>
          {options.domains.map((v) => (
            <option key={v}>{v}</option>
          ))}
        </select>
        <select value={source} onChange={(e) => setSource(e.target.value)} aria-label="Filter by source system">
          <option value="">source system</option>
          {options.sources.map((v) => (
            <option key={v}>{v}</option>
          ))}
        </select>
        <select value={entity} onChange={(e) => setEntity(e.target.value)} aria-label="Filter by entity">
          <option value="">entity</option>
          {options.entities.map((v) => (
            <option key={v}>{v}</option>
          ))}
        </select>
        <select
          value={destination}
          onChange={(e) => setDestination(e.target.value)}
          aria-label="Filter by destination system"
        >
          <option value="">destination system</option>
          {options.destinations.map((v) => (
            <option key={v}>{v}</option>
          ))}
        </select>
        <select
          value={lifecycle}
          onChange={(e) => setLifecycle(e.target.value)}
          aria-label="Filter by lifecycle"
        >
          <option value="">lifecycle</option>
          {options.lifecycles.map((v) => (
            <option key={v}>{v}</option>
          ))}
        </select>
        <input
          type="search"
          className="catalog-filter"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Filter"
          aria-label="Filter systems"
        />
      </div>

      <table className="board systems-table">
        <thead>
          <tr>
            <th>name</th>
            <th>domain</th>
            <th>source systems</th>
            <th>entity</th>
            <th>destination systems</th>
            <th>lifecycle</th>
          </tr>
        </thead>
        <tbody>
          {filtered.map((row) => (
            <tr key={row.system}>
              <td>
                <Link to={`/systems/${row.domain}/${row.system}`}>
                  <strong>{row.system}</strong>
                </Link>{' '}
                {!row.consistent && <span className="chip bad">disagree</span>}
                {row.pendingGates > 0 && <span className="chip warn">gate</span>}
              </td>
              <td className="muted">{row.domain}</td>
              <td>
                <NeighborList neighbors={row.sources} />
              </td>
              <td>
                <span className="row" style={{ gap: 6 }}>
                  {row.entities.map((e) => (
                    <span key={e} className="chip mono">
                      {e}
                    </span>
                  ))}
                </span>
              </td>
              <td>
                <NeighborList neighbors={row.destinations} />
              </td>
              <td className="muted">{row.lifecycle}</td>
            </tr>
          ))}
          {filtered.length === 0 && (
            <tr>
              <td colSpan={6}>
                <span className="muted">No system matches this filter. Widen it.</span>
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <div className="provenance">
        sources and destinations join declared connectors with same-shape (fingerprint) usage —
        never invented wiring. lifecycle derives from <code>deploy status</code>: production when
        every component runs in prod.
      </div>
    </>
  )
}

