import { NavLink, Outlet } from 'react-router-dom'
import { mockSource } from '../data/mock'
import { useData } from '../data/useData'

// The catalog section: a tree of the estate (domain -> system -> component)
// in a second sidebar, with the selected entry's detail as the content.

export function CatalogLayout() {
  const estate = useData(() => mockSource.estate())
  if (!estate) return null

  return (
    <div className="catalog-layout">
      <aside className="cat-tree" aria-label="Catalog tree">
        <NavLink to="/catalog" end className={({ isActive }) => (isActive ? 'all active' : 'all')}>
          All systems
        </NavLink>
        {estate.domains.map(({ domain, systems }) => (
          <div key={domain} className="cat-group">
            <div className="eyebrow">{domain}</div>
            {systems.map((system) => (
              <div key={system.urn}>
                <NavLink
                  to={`/catalog/${system.domain}/${system.system}`}
                  end
                  className={({ isActive }) => `cat-system${isActive ? ' active' : ''}`}
                >
                  {system.system}
                  {!system.consistent && <span className="dot bad" title="environments disagree" />}
                  {system.pendingGates > 0 && <span className="dot warn" title="gate awaiting sync" />}
                </NavLink>
                {system.components.map((component) => (
                  <NavLink
                    key={component.urn}
                    to={`/catalog/${system.domain}/${system.system}/${component.component}`}
                    className={({ isActive }) => `cat-component${isActive ? ' active' : ''}`}
                  >
                    {component.component}
                  </NavLink>
                ))}
              </div>
            ))}
          </div>
        ))}
      </aside>
      <div className="cat-content">
        <Outlet />
      </div>
    </div>
  )
}

import { Link, useParams } from 'react-router-dom'
import { EnvLadder, Provenance, fmtTime } from '../components/shared'
import { mockSource } from '../data/mock'
import { useData } from '../data/useData'
import { shortSha } from '../domain/urn'
import { monitoringLink } from '../fixtures/knowledge'

export function ComponentPage() {
  const { domain = '', system = '', component = '' } = useParams()
  const view = useData(() => mockSource.system(domain, system), [domain, system])
  if (!view) return <div className="empty">No host has emitted a topology for this system.</div>

  const topo = (view.topology.components ?? []).find((c) => c.name === component)
  const status = view.statuses.find((s) => s.component === component)
  const releases = view.releases.filter((r) => r.payload.component === component)

  if (!topo) {
    return (
      <div className="empty">
        No component named <span className="mono">{component}</span> in the declared topology of{' '}
        <Link to={`/catalog/${domain}/${system}`}>{system}</Link>.
      </div>
    )
  }

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">
          catalog · {domain} · <Link to={`/catalog/${domain}/${system}`}>{system}</Link>
        </div>
        <h1>
          <span className="mono">{component}</span>
        </h1>
        <div className="row">
          <span className="chip">{topo.kind}</span>
          <a
            className="chip external-link"
            href={monitoringLink(system, component)}
            target="_blank"
            rel="noreferrer"
          >
            monitoring
          </a>
        </div>
      </header>

      <div className="card" style={{ marginBottom: 20 }}>
        <h3>Wiring</h3>
        <div className="small muted">
          {(topo.subscribes ?? []).map((s) => (
            <div key={s.topic}>
              subscribes <span className="mono">{s.topic}</span>
            </div>
          ))}
          {(topo.publishes ?? []).map((p) => (
            <div key={p.topic}>
              publishes <span className="mono">{p.topic}</span>
            </div>
          ))}
          {(topo.connectors ?? []).map((c) => (
            <div key={c.connector}>
              {c.direction === 'in' ? (
                <>
                  <span className="mono">{c.connector}</span> -&gt; component
                </>
              ) : (
                <>
                  component -&gt; <span className="mono">{c.connector}</span>
                </>
              )}
            </div>
          ))}
        </div>
      </div>

      {status && (
        <div className="card" style={{ marginBottom: 20 }}>
          <h3>Environments</h3>
          <EnvLadder environments={status.status.environments} />
          <div className="summary-sentence" style={{ marginTop: 8 }}>
            {status.status.summary}
          </div>
          {status.status.notes?.map((note) => (
            <div key={note} className="small muted">
              — {note}
            </div>
          ))}
          <Provenance
            source={{ command: 'deploy status', version: '0.9.2', actor: 'reconciler' }}
            at={status.observedAt}
          />
        </div>
      )}

      <h2>Releases</h2>
      {releases.length === 0 ? (
        <div className="empty">No release manifest names this component yet.</div>
      ) : (
        <table className="board">
          <thead>
            <tr>
              <th>version</th>
              <th>created</th>
              <th>source</th>
              <th>changes</th>
            </tr>
          </thead>
          <tbody>
            {releases.map((release) => (
              <tr key={release.id}>
                <td>
                  <span className="mono">{release.payload.version}</span>
                  {release.payload.notes && (
                    <div className="small muted">{release.payload.notes}</div>
                  )}
                </td>
                <td className="small muted">
                  {fmtTime(release.payload.createdAt)} by {release.payload.createdBy}
                </td>
                <td>
                  <span className="mono small">{shortSha(release.payload.source.commit)}</span>
                </td>
                <td className="small muted">
                  {(release.payload.changes ?? []).map((change) => (
                    <div key={change.commit}>
                      <span className="mono">{shortSha(change.commit)}</span> {change.subject}
                    </div>
                  ))}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  )
}

