}

.cat-tree .all.active {
  color: var(--verdigris-deep);
  background: var(--verdigris-bg);
}

.cat-tree .cat-group {
  margin-bottom: 10px;
}

.cat-tree .eyebrow {
  padding: 6px 10px 2px;
  margin-bottom: 0;
}

.cat-tree a {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 6px;
  color: var(--muted);
}

.cat-tree a:hover {
  color: var(--ink);
  background: rgba(42, 122, 104, 0.06);
  text-decoration: none;
}

.cat-tree .cat-system {
  font-weight: 600;
  color: var(--ink);
}

.cat-tree .cat-component {
  font-family: var(--mono);
  font-size: 12px;
  padding-left: 24px;
}

.cat-tree .cat-system.active,
.cat-tree .cat-component.active {
  color: var(--verdigris-deep);
  background: var(--verdigris-bg);
}

.cat-tree .dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  display: inline-block;
  flex: none;
}

.cat-tree .dot.bad {
  background: var(--rust);
}

.cat-tree .dot.warn {
  background: var(--amber);
}

@media (max-width: 900px) {
  .catalog-layout {
    grid-template-columns: 1fr;
  }

  .cat-tree {
    position: static;
    border-right: none;
    border-bottom: 1px solid var(--hairline);
    padding-bottom: 12px;
    min-height: 0;
  }
}

